insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('adm-cm:40-1529d23754','adm-cm',40,'¿Qué es un controlador o driver?','["Una aplicación del sistema operativo para crear y restaurar copias de seguridad de los archivos", "El usuario con permisos de administrador que puede instalar y desinstalar programas en el equipo", "Un componente físico de la placa base que conecta el procesador con el resto de dispositivos", "Un programa que permite al sistema operativo comunicarse con un dispositivo de hardware"]'::jsonb,3,'Software','Cada dispositivo necesita su controlador para funcionar correctamente.',null),
('adm-cm:40-7d0fcb6d79','adm-cm',40,'La computación en la nube (cloud computing) consiste en:','["Conectar varios ordenadores de una misma oficina en una red local sin cables mediante tecnología wifi", "Guardar archivos en una memoria USB externa", "Usar recursos informáticos, como almacenamiento o aplicaciones, ofrecidos a través de internet", "Instalar programas solo desde un CD o DVD"]'::jsonb,2,'Cloud computing','Ejemplos: OneDrive, Google Drive o Microsoft 365.',null),
('adm-cm:40-22290331f6','adm-cm',40,'¿Qué significan las siglas SaaS en la computación en la nube?','["Servidor de aplicaciones en red", "Seguridad como servicio", "Sistema de almacenamiento seguro", "Software como servicio"]'::jsonb,3,'Cloud computing','Junto a SaaS están IaaS (infraestructura como servicio) y PaaS (plataforma como servicio).',null),
('adm-cm:40-1490c87c58','adm-cm',40,'¿Cuántos bits forman un nibble o cuarteto?','["2", "4", "16", "8"]'::jsonb,1,'Unidades de información','Un nibble son 4 bits, la mitad de un byte.',null),
('adm-cm:40-b50afb37a3','adm-cm',40,'En el sistema binario tradicional, un gigabyte equivale a:','["1.024 megabytes", "1.000 megabytes", "2.048 megabytes", "512 megabytes"]'::jsonb,0,'Unidades de información','Cada unidad es 1.024 veces la anterior: 1 GB = 1.024 MB.',null),
('adm-cm:40-916444c7e7','adm-cm',40,'El número binario 1111 equivale en decimal a:','["11", "15", "14", "16"]'::jsonb,1,'Representación de la información','8 + 4 + 2 + 1 = 15.',null),
('adm-cm:40-6ab5e04fc8','adm-cm',40,'¿Qué sistema de numeración utiliza los dígitos del 0 al 9 y las letras de la A a la F?','["El hexadecimal", "El binario", "El octal", "El decimal"]'::jsonb,0,'Representación de la información','El sistema hexadecimal tiene base 16: 0-9 y A-F.',null),
('adm-cm:40-92e653e1aa','adm-cm',40,'La memoria ROM se caracteriza por ser:','["Volátil y de solo lectura", "No volátil y, en principio, de solo lectura", "Volátil y de lectura y escritura", "Una memoria de almacenamiento masivo externa"]'::jsonb,1,'Memoria','La ROM conserva los datos sin corriente y está pensada para leerse, no para escribirse en el uso normal.',null),
('adm-cm:40-ddb6f8af2e','adm-cm',40,'¿Qué componente conecta todos los elementos internos del ordenador y permite que se comuniquen?','["La placa base", "El disipador", "La fuente de alimentación", "La tarjeta gráfica"]'::jsonb,0,'Hardware','La placa base aloja y comunica el procesador, la memoria y el resto de componentes.',null),
('adm-cm:40-9772830649','adm-cm',40,'La GPU de un ordenador es:','["La unidad principal de almacenamiento", "El procesador especializado en gráficos", "El controlador de la red inalámbrica", "La memoria intermedia del disco duro"]'::jsonb,1,'Hardware','La GPU (unidad de procesamiento gráfico) se encarga de calcular y mostrar las imágenes.',null),
('adm-cm:40-130ced6056','adm-cm',40,'¿Cuál de los siguientes es un periférico de salida?','["El micrófono", "El lector de códigos de barras", "La impresora", "El ratón"]'::jsonb,2,'Periféricos','La impresora saca información del ordenador; los otros tres la introducen.',null),
('adm-cm:40-8b0dd827b2','adm-cm',40,'Un disco duro tradicional (HDD) guarda la información:','["En platos magnéticos que giran", "En chips de memoria flash", "En la memoria RAM del equipo", "En discos ópticos grabados con láser"]'::jsonb,0,'Almacenamiento','El HDD usa platos magnéticos y un cabezal móvil; el SSD usa memoria flash sin partes móviles.',null),
('adm-cm:40-740962317a','adm-cm',40,'Un procesador de textos es un ejemplo de:','["Controlador de dispositivo", "Software de aplicación", "Firmware", "Software de sistema"]'::jsonb,1,'Tipos de software','Los programas para tareas del usuario (textos, hojas de cálculo) son software de aplicación.',null),
('adm-cm:40-60ca95cf6a','adm-cm',40,'En la computación en la nube, IaaS significa:','["Integración como servicio", "Internet como servicio", "Infraestructura como servicio", "Información como servicio"]'::jsonb,2,'Cloud computing','IaaS ofrece servidores, almacenamiento y redes virtuales como servicio.',null),
('adm-cm:40-6065490d5a','adm-cm',40,'Un gusano informático se caracteriza por:','["Propagarse por sí mismo a otros equipos a través de la red", "Cifrar los archivos del usuario y pedir un rescate económico para liberarlos", "Mostrar publicidad no deseada en el navegador", "Registrar las teclas que pulsa el usuario"]'::jsonb,0,'Seguridad','El gusano se replica solo; el ransomware cifra, el adware muestra anuncios y el keylogger registra pulsaciones.',null),
('adm-cm:40-cff4eefa02','adm-cm',40,'Una copia de seguridad diferencial guarda:','["Los archivos modificados desde la última copia de cualquier tipo", "Solo los archivos creados ese mismo día", "Todos los archivos del equipo cada vez", "Los archivos modificados desde la última copia completa"]'::jsonb,3,'Copias de seguridad','La diferencial toma como referencia la última copia completa; la incremental, la última copia de cualquier tipo.',null),
('adm-cm:40-f409a95b55','adm-cm',40,'La verificación en dos pasos consiste en:','["Iniciar sesión a la vez desde dos dispositivos", "Usar dos contraseñas distintas, una para el usuario y otra para el equipo, en cada acceso", "Cambiar la contraseña cada dos meses", "Pedir, además de la contraseña, un segundo factor, como un código en el móvil"]'::jsonb,3,'Seguridad','Combina algo que sabes (contraseña) con algo que tienes (móvil, llave) o que eres (huella).',null),
('adm-cm:40-32985bce1a','adm-cm',40,'Una red que abarca una zona geográfica amplia, como un país, se denomina:','["WAN", "PAN", "WLAN", "LAN"]'::jsonb,0,'Redes','WAN es red de área amplia; LAN, local; PAN, personal; WLAN, local inalámbrica.',null),
('adm-cm:40-07c723aed2','adm-cm',40,'¿Qué protocolo se usa para transferir páginas web de forma cifrada?','["SMTP", "HTTPS", "HTTP", "FTP"]'::jsonb,1,'Protocolos de internet','HTTPS es HTTP sobre una conexión cifrada con TLS. FTP transfiere archivos y SMTP envía correo.',null),
('adm-cm:40-80f100689e','adm-cm',40,'¿Qué función cumple el sistema DNS en internet?','["Asignar una dirección de correo a cada usuario", "Traducir los nombres de dominio en direcciones IP", "Bloquear el acceso a páginas peligrosas", "Cifrar las comunicaciones entre el navegador y el servidor"]'::jsonb,1,'DNS','Gracias al DNS escribimos «boe.es» en lugar de la dirección IP del servidor.',null),
('adm-cm:40-c92959ffef','adm-cm',40,'En la dirección https://www.boe.es/diario_boe/, ¿cuál es el dominio de primer nivel?','["boe", "diario_boe", ".es", "www"]'::jsonb,2,'Dominios','El dominio de primer nivel es la última parte del nombre: .es, .com, .org, etc.',null),
('adm-cm:40-5183c7f897','adm-cm',40,'¿Qué protocolo se utiliza para enviar correo electrónico?','["HTTP", "POP3", "SMTP", "IMAP"]'::jsonb,2,'Correo electrónico','POP3 e IMAP se usan para recibir o consultar el correo.',null),
('adm-cm:40-e3dcabf7de','adm-cm',40,'¿Quién creó la World Wide Web?','["Bill Gates, en la empresa Microsoft", "Tim Berners-Lee, en el CERN", "Linus Torvalds, en la Universidad de Helsinki", "Vinton Cerf, en el proyecto ARPANET"]'::jsonb,1,'Historia de internet','La propuso en 1989 y desarrolló el primer navegador y servidor web.',null),
('adm-cm:40-341866bae8','adm-cm',40,'El lenguaje de marcado con el que se escriben las páginas web es:','["HTML", "XML", "CSS", "SQL"]'::jsonb,0,'Lenguajes web','CSS se usa para el diseño o estilo, SQL para bases de datos y XML para intercambio de datos.',null),
('adm-cm:40-91904ce258','adm-cm',40,'Una cookie es:','["Un programa malicioso que se instala en el equipo al visitar determinadas páginas web sin que el usuario lo sepa", "Un pequeño archivo que el sitio web guarda en el navegador del usuario para recordar información", "Un buscador alternativo a Google", "Un certificado digital que acredita que la web es segura y que pertenece a la organización que dice ser"]'::jsonb,1,'Navegación','Sirve, por ejemplo, para recordar el idioma, la sesión iniciada o el carrito de compra.',null),
('adm-cm:40-266ddb4f8a','adm-cm',40,'La navegación InPrivate o de incógnito:','["Impide que el proveedor de internet vea las páginas visitadas", "No guarda en el equipo el historial, las cookies ni los datos de formularios al cerrar la ventana", "Oculta la dirección IP del usuario a todos los sitios web que visita, de modo que navega de forma anónima", "Protege el equipo frente a cualquier virus"]'::jsonb,1,'Navegación privada','No hace al usuario anónimo frente a los sitios web, su empresa o su proveedor de internet.',null),
('adm-cm:40-b263a0333e','adm-cm',40,'En Microsoft Edge, ¿qué combinación abre una nueva ventana InPrivate?','["Ctrl + Mayús + I", "Ctrl + Mayús + P", "Ctrl + Mayús + N", "Ctrl + N"]'::jsonb,2,'Atajos del navegador','En Firefox, la ventana privada se abre con Ctrl + Mayús + P.',null),
('adm-cm:40-f47670038e','adm-cm',40,'En los navegadores, Ctrl + Mayús + T sirve para:','["Traducir la página al idioma configurado en el navegador", "Cerrar todas las pestañas abiertas salvo la actual", "Abrir una nueva pestaña en blanco junto a la actual", "Volver a abrir la última pestaña cerrada"]'::jsonb,3,'Atajos del navegador','Ctrl + T abre una pestaña nueva y Ctrl + W cierra la actual.',null),
('adm-cm:40-12cb63d7a9','adm-cm',40,'¿Qué combinación de teclas añade la página actual a Favoritos o Marcadores?','["Ctrl + D", "Ctrl + B", "Ctrl + F", "Ctrl + H"]'::jsonb,0,'Atajos del navegador','Ctrl + F busca en la página y Ctrl + H abre el historial.',null),
('adm-cm:40-09d98b1aed','adm-cm',40,'En los navegadores, Ctrl + J abre:','["Las descargas", "Los favoritos", "El historial", "Una pestaña nueva"]'::jsonb,0,'Atajos del navegador','Ctrl + H abre el historial.',null),
('adm-cm:40-4465a91f37','adm-cm',40,'La tecla F5 en un navegador sirve para:','["Actualizar o recargar la página", "Ir a la página de inicio configurada en el navegador", "Activar o desactivar el modo de pantalla completa", "Imprimir la página o guardarla como PDF"]'::jsonb,0,'Atajos del navegador','F11 activa la pantalla completa.',null),
('adm-cm:40-840dc631c4','adm-cm',40,'Una intranet es:','["La parte de internet que solo puede visitarse con navegadores especiales y que no aparece indexada en los buscadores", "Una red que conecta varias organizaciones entre sí a través de satélites", "Una red privada de una organización que usa las tecnologías de internet y solo es accesible para sus miembros", "Una red pública mundial accesible para cualquier persona"]'::jsonb,2,'Redes','Si se abre a usuarios externos autorizados (proveedores, clientes), se habla de extranet.',null),
('adm-cm:40-39fcc90de4','adm-cm',40,'¿Qué es una dirección IP?','["El nombre de dominio con el que se identifica una página web en internet", "La contraseña que protege el acceso a la red wifi de una casa u oficina", "Un número que identifica a un dispositivo dentro de una red", "El código de un certificado digital"]'::jsonb,2,'Direccionamiento','Existen direcciones IPv4 (32 bits) e IPv6 (128 bits).',null),
('adm-cm:40-4690cc0d7e','adm-cm',40,'¿Cuántos bits tiene una dirección IPv6?','["256", "128", "64", "32"]'::jsonb,1,'Direccionamiento','Las direcciones IPv4 tienen 32 bits.',null),
('adm-cm:40-e3bb5f82aa','adm-cm',40,'La URL es:','["El nombre del programa que se usa para navegar por internet", "El protocolo de cifrado que utilizan las páginas web seguras", "La dirección que identifica un recurso en internet", "El servidor físico en el que se aloja una página web"]'::jsonb,2,'Navegación','Por ejemplo, https://administracion.gob.es.',null),
('adm-cm:40-0dcae52c2b','adm-cm',40,'¿Qué indica el candado que aparece junto a la dirección en el navegador?','["Que la conexión con el sitio está cifrada", "Que el sitio es oficial y no puede ser fraudulento", "Que la web está bloqueada", "Que la página no usa cookies"]'::jsonb,0,'Seguridad','Una web fraudulenta también puede tener conexión cifrada; el candado no garantiza que sea legítima.',null),
('adm-cm:40-f3695db272','adm-cm',40,'Un motor de búsqueda o buscador es:','["La aplicación que muestra las páginas web en pantalla", "Un programa para descargar archivos de forma más rápida", "Un sistema que localiza páginas web según las palabras clave que introduce el usuario", "Un servidor que asigna los nombres de dominio a las organizaciones que los solicitan y pagan por ellos"]'::jsonb,2,'Buscadores','La aplicación que muestra las páginas es el navegador.',null),
('adm-cm:40-beef377c0e','adm-cm',40,'En la mayoría de buscadores, escribir una frase entre comillas sirve para:','["Excluir esas palabras de la búsqueda", "Buscar exactamente esa frase", "Buscar sinónimos", "Buscar solo imágenes"]'::jsonb,1,'Buscadores','El signo menos delante de una palabra la excluye de los resultados.',null),
('adm-cm:40-56479b523d','adm-cm',40,'El protocolo FTP se usa para:','["Cifrar las páginas web que contienen datos personales", "Enviar mensajes de correo electrónico a otros usuarios", "Transferir archivos entre equipos", "Resolver los nombres de dominio en direcciones IP"]'::jsonb,2,'Protocolos de internet','Existe una versión segura llamada SFTP o FTPS.',null),
('adm-cm:40-81563429f8','adm-cm',40,'¿Qué es la caché del navegador?','["La lista de contraseñas y datos de inicio de sesión que el usuario ha decidido guardar en el navegador", "La carpeta del disco duro en la que se guardan por defecto todos los archivos descargados de internet", "Un almacenamiento temporal de elementos de las páginas visitadas para cargarlas más rápido", "El registro de las páginas marcadas como favoritas"]'::jsonb,2,'Navegación','Borrar la caché puede resolver problemas de visualización de algunas páginas.',null),
('adm-cm:40-a7c19de8d1','adm-cm',40,'¿Qué es un navegador web?','["Una red privada virtual", "Un servidor que almacena páginas web y las envía a los usuarios que las solicitan", "Un protocolo de transferencia de archivos", "Una aplicación que permite acceder a las páginas web y visualizarlas"]'::jsonb,3,'Navegadores','Ejemplos: Microsoft Edge, Google Chrome, Mozilla Firefox o Safari.',null),
('adm-cm:40-1b763140d4','adm-cm',40,'¿Qué es una VPN?','["Un servidor de correo electrónico seguro", "Una red privada virtual que crea una conexión cifrada a través de internet", "Un tipo de virus que se propaga por la red infectando los equipos conectados a ella", "Un navegador especial que deben usar los empleados públicos para acceder a la sede"]'::jsonb,1,'Redes','Permite, por ejemplo, teletrabajar accediendo a la red interna de la organización.',null),
('adm-cm:40-725432b36f','adm-cm',40,'¿Qué protocolo permite leer el correo manteniendo los mensajes sincronizados en el servidor?','["FTP", "SMTP", "IMAP", "POP3"]'::jsonb,2,'Correo electrónico','IMAP sincroniza con el servidor; POP3 descarga los mensajes y SMTP sirve para enviar.',null),
('adm-cm:40-232d50e5b1','adm-cm',40,'¿Cuántos bits tiene una dirección IPv4?','["64", "128", "32", "16"]'::jsonb,2,'Direccionamiento','IPv4 usa 32 bits (cuatro números de 0 a 255); IPv6, 128.',null),
('adm-cm:40-335c621b91','adm-cm',40,'¿Cuál de estos es un dominio de primer nivel genérico?','[".fr", ".es", ".org", ".mx"]'::jsonb,2,'Dominios','.org es genérico; .es, .fr y .mx son dominios territoriales de países.',null),
('adm-cm:40-13dd4b0819','adm-cm',40,'¿Qué puerto usa por defecto el protocolo HTTPS?','["21", "443", "25", "80"]'::jsonb,1,'Protocolos de internet','HTTPS usa el 443; HTTP, el 80; FTP, el 21, y SMTP, el 25.',null),
('adm-cm:40-66a0f349a1','adm-cm',40,'En un correo electrónico, los destinatarios añadidos en CCO:','["Pueden modificar el mensaje antes de leerlo", "Reciben el mensaje solo si lo abre el destinatario principal", "Reciben una copia sin los archivos adjuntos", "No son visibles para el resto de destinatarios"]'::jsonb,3,'Correo electrónico','CCO (copia oculta) envía el mensaje sin mostrar esas direcciones a los demás.',null),
('adm-cm:40-1417587f04','adm-cm',40,'Un router es un dispositivo que:','["Almacena las páginas web que se visitan", "Traduce los nombres de dominio de las páginas a sus direcciones IP numéricas", "Protege el equipo frente a los virus", "Conecta redes distintas y encamina los paquetes de datos entre ellas"]'::jsonb,3,'Redes','El router interconecta redes (por ejemplo, la de casa con internet) y decide por dónde enviar los datos.',null),
('adm-cm:40-f096487b2d','adm-cm',40,'¿Qué entidad pública gestiona el registro de los dominios .es?','["El Ministerio de Hacienda", "Red.es", "El Instituto Nacional de Ciberseguridad", "La ICANN directamente"]'::jsonb,1,'Dominios','El registro de nombres de dominio bajo .es lo gestiona la entidad pública Red.es.',null),
('adm-cm:40-d354cab4aa','adm-cm',40,'¿Cuál de los siguientes NO es un navegador web?','["Outlook", "Mozilla Firefox", "Microsoft Edge", "Google Chrome"]'::jsonb,0,'Navegadores','Outlook es un gestor de correo y calendario; los otros tres son navegadores.',null),
('adm-cm:40-756fe36fc9','adm-cm',40,'En los navegadores, Ctrl + T sirve para:','["Volver a abrir la última pestaña cerrada", "Abrir una pestaña nueva", "Cerrar la pestaña actual", "Abrir una ventana privada"]'::jsonb,1,'Atajos del navegador','Ctrl + T abre una pestaña; Ctrl + W la cierra y Ctrl + Mayús + T reabre la última cerrada.',null),
('adm-cm:40-fa76334d87','adm-cm',40,'En los navegadores, Ctrl + W sirve para:','["Guardar la página", "Abrir el historial", "Cerrar la pestaña actual", "Abrir una pestaña nueva"]'::jsonb,2,'Atajos del navegador','Ctrl + W cierra la pestaña activa.',null),
('adm-cm:40-c54e16b9dd','adm-cm',40,'El ancho de banda de una conexión indica:','["La distancia máxima entre el equipo y el router", "La cantidad de datos que puede transmitir por unidad de tiempo", "El número de dispositivos que se pueden conectar", "El tiempo que tarda en cargar por completo una página web concreta"]'::jsonb,1,'Redes','Se mide en bits por segundo (Mbps, Gbps).',null),
('adm-cm:40-4b43009330','adm-cm',40,'Un hipervínculo es:','["Un archivo temporal del navegador", "Un elemento que, al pulsarlo, lleva a otra página o recurso", "Un tipo de dirección IP", "Un programa del navegador que bloquea las ventanas emergentes publicitarias"]'::jsonb,1,'Navegación','Los hipervínculos o enlaces conectan páginas y recursos en la web.',null),
('adm-cm:41-4ff58ecb65','adm-cm',41,'En Windows 11, ¿qué combinación de teclas muestra u oculta el escritorio?','["Windows + L", "Windows + D", "Windows + M + Mayús", "Windows + E"]'::jsonb,1,'Atajos de Windows','Windows + E abre el Explorador de archivos y Windows + L bloquea el equipo.',null),
('adm-cm:41-409a2e2c1e','adm-cm',41,'En Windows 11, la combinación Windows + L sirve para:','["Abrir el Explorador de archivos", "Cerrar la sesión y apagar el equipo", "Bloquear el equipo", "Abrir la configuración de idioma"]'::jsonb,2,'Atajos de Windows','Para volver a entrar hay que identificarse (contraseña, PIN o Windows Hello).',null),
('adm-cm:41-44b382f58e','adm-cm',41,'¿Qué combinación de teclas abre el historial del portapapeles en Windows 11?','["Windows + V", "Ctrl + V", "Ctrl + Mayús + V", "Windows + C"]'::jsonb,0,'Atajos de Windows','Ctrl + V pega el último elemento copiado. El historial debe estar activado en Configuración.',null),
('adm-cm:41-2d6af7ca93','adm-cm',41,'En Windows 11, Windows + Mayús + S permite:','["Abrir el menú de apagado, reinicio y suspensión del sistema operativo", "Capturar una parte de la pantalla con la herramienta Recortes", "Cambiar entre los distintos escritorios virtuales creados por el usuario", "Guardar el documento que está abierto con otro nombre o en otra carpeta"]'::jsonb,1,'Atajos de Windows','La captura se copia en el portapapeles y puede editarse en Recortes.',null),
('adm-cm:41-7410e0b814','adm-cm',41,'¿Qué combinación abre directamente el Administrador de tareas?','["Windows + Ctrl + Esc", "Ctrl + Mayús + Esc", "Windows + Tab", "Alt + F4"]'::jsonb,1,'Atajos de Windows','Ctrl + Alt + Supr muestra una pantalla desde la que también puede abrirse.',null),
('adm-cm:41-9c129f8dcb','adm-cm',41,'En Windows 11, la combinación Windows + Tab abre:','["El menú Inicio con las aplicaciones ancladas y los archivos recomendados recientemente", "El centro de notificaciones", "El cuadro Ejecutar para escribir el nombre de un programa, carpeta o comando", "La vista de tareas, con las ventanas abiertas y los escritorios virtuales"]'::jsonb,3,'Atajos de Windows','Alt + Tab permite cambiar rápidamente entre ventanas abiertas.',null),
('adm-cm:41-2788971d44','adm-cm',41,'En Windows 11, la combinación Windows + I abre:','["Configuración", "El Explorador de archivos", "El Panel de control", "La búsqueda de Windows"]'::jsonb,0,'Atajos de Windows','La aplicación Configuración sustituye progresivamente al Panel de control.',null),
('adm-cm:41-339eed0dc9','adm-cm',41,'¿Qué combinación de teclas abre el cuadro de diálogo Ejecutar?','["Windows + E", "Ctrl + R", "Windows + R", "Alt + R"]'::jsonb,2,'Atajos de Windows','Permite abrir programas, carpetas o comandos escribiendo su nombre, por ejemplo «cmd».',null),
('adm-cm:41-645f3d54be','adm-cm',41,'Al eliminar un archivo del disco duro con Mayús + Supr en Windows:','["Se oculta al usuario, pero sigue ocupando espacio en la misma carpeta del disco", "Se envía a la Papelera de reciclaje, igual que si se pulsara solo la tecla Supr", "Se mueve a la carpeta Documentos", "Se elimina de forma permanente, sin pasar por la Papelera de reciclaje"]'::jsonb,3,'Papelera de reciclaje','Normalmente Windows pide confirmación antes de eliminarlo definitivamente.',null),
('adm-cm:41-4dd33da07a','adm-cm',41,'¿Qué es Copilot en Windows 11?','["El antivirus que viene integrado en el sistema operativo Windows", "Una herramienta para hacer copias de seguridad de los archivos en la nube", "El gestor de contraseñas integrado en el navegador Microsoft Edge", "Un asistente de inteligencia artificial de Microsoft"]'::jsonb,3,'Copilot','Permite hacer preguntas, redactar textos o resumir contenidos en lenguaje natural. Algunos teclados recientes incluyen una tecla Copilot.',null),
('adm-cm:41-68a8c17f64','adm-cm',41,'¿Qué antivirus incluye Windows 11 de forma integrada?','["BitLocker", "Windows Hello", "Microsoft Defender", "OneDrive"]'::jsonb,2,'Seguridad de Windows','Windows Hello sirve para iniciar sesión con rostro, huella o PIN; BitLocker cifra unidades y OneDrive es almacenamiento en la nube.',null),
('adm-cm:41-6e5207130f','adm-cm',41,'BitLocker es una función de Windows que sirve para:','["Limitar el tiempo que cada usuario puede usar los programas del equipo", "Cifrar unidades de disco para proteger los datos", "Comprimir carpetas y archivos en formato ZIP para que ocupen menos", "Bloquear las ventanas emergentes que abren las páginas web en el navegador"]'::jsonb,1,'Seguridad de Windows','Si se pierde el equipo, los datos no pueden leerse sin la clave.',null),
('adm-cm:41-838c963031','adm-cm',41,'Windows Hello permite:','["Traducir automáticamente al español el texto que aparece en la pantalla", "Iniciar sesión con reconocimiento facial, huella dactilar o PIN", "Saludar al usuario con un mensaje de voz al arrancar", "Hacer videollamadas con otros usuarios de Windows a través de la cámara del equipo"]'::jsonb,1,'Inicio de sesión','Es una alternativa más segura y cómoda a la contraseña.',null),
('adm-cm:41-fc55779ddf','adm-cm',41,'¿Qué función de Windows 11 permite organizar las ventanas en distintas disposiciones de la pantalla al pasar el ratón por el botón Maximizar?','["Los escritorios virtuales de la vista de tareas", "La vista de tareas con todas las ventanas abiertas", "Los diseños de ajuste (Snap layouts)", "El modo tableta para pantallas táctiles"]'::jsonb,2,'Ventanas','También pueden abrirse con Windows + Z.',null),
('adm-cm:41-29719ddad5','adm-cm',41,'¿Qué ocurre con un archivo eliminado de una memoria USB en Windows?','["Se mueve a una carpeta oculta de la propia memoria", "Se elimina definitivamente, porque las unidades extraíbles no usan la Papelera de reciclaje", "Se guarda una copia en OneDrive", "Se envía a la Papelera de reciclaje del ordenador, desde donde puede restaurarse en cualquier momento"]'::jsonb,1,'Papelera de reciclaje','Por eso conviene tener cuidado al borrar archivos de unidades extraíbles.',null),
('adm-cm:41-4dc77e6cc3','adm-cm',41,'¿Qué sistema de archivos no admite archivos individuales mayores de 4 GB?','["exFAT", "FAT32", "ReFS", "NTFS"]'::jsonb,1,'Sistemas de archivos','NTFS es el sistema de archivos habitual de Windows; exFAT es frecuente en memorias USB y tarjetas.',null),
('adm-cm:41-a21cfbdb91','adm-cm',41,'El Control de cuentas de usuario (UAC) de Windows:','["Pide confirmación antes de realizar cambios que requieren permisos de administrador", "Registra las horas de conexión y desconexión de cada usuario para controlar su jornada", "Limita el número máximo de cuentas de usuario que pueden crearse en un mismo equipo", "Elimina las cuentas que no se usan en treinta días"]'::jsonb,0,'Cuentas de usuario','Ayuda a evitar que programas maliciosos hagan cambios sin que el usuario lo sepa.',null),
('adm-cm:41-8be3eeed8d','adm-cm',41,'¿En qué se diferencia la hibernación de la suspensión en Windows?','["La suspensión apaga por completo el equipo y la hibernación solo apaga la pantalla", "La hibernación guarda la sesión en el disco y apaga el equipo; la suspensión la mantiene en la memoria con un consumo mínimo", "La hibernación cierra todos los programas sin guardar los cambios; la suspensión los guarda automáticamente en el disco duro del equipo", "No hay ninguna diferencia, son dos nombres de la misma función"]'::jsonb,1,'Opciones de energía','Por eso la reanudación desde la suspensión es más rápida.',null),
('adm-cm:41-3fac0a6a4f','adm-cm',41,'¿Qué combinación abre el menú de vínculo rápido (clic derecho del botón Inicio) en Windows 11?','["Windows + X", "Windows + Q", "Alt + Inicio", "Ctrl + X"]'::jsonb,0,'Atajos de Windows','Da acceso a herramientas como el Administrador de dispositivos, la Administración de discos o Terminal.',null),
('adm-cm:41-ee854daeed','adm-cm',41,'La tecla Windows + Impr Pant en Windows 11:','["Imprime directamente la pantalla completa en la impresora que esté configurada como predeterminada", "Abre el cuadro de diálogo de impresión del programa activo", "Captura la pantalla completa y la guarda como imagen en la carpeta Capturas de pantalla", "Copia solo la ventana activa en el portapapeles"]'::jsonb,2,'Capturas de pantalla','La carpeta Capturas de pantalla está dentro de Imágenes. Alt + Impr Pant copia solo la ventana activa.',null),
('adm-cm:41-4c2a16892f','adm-cm',41,'¿Qué combinación abre el panel de emojis en Windows 11?','["Windows + punto (.)", "Windows + E", "Alt + punto (.)", "Ctrl + Mayús + E"]'::jsonb,0,'Atajos de Windows','También permite insertar símbolos y GIF.',null),
('adm-cm:41-31a8376f39','adm-cm',41,'En Windows 11, Windows + A abre:','["Las aplicaciones ancladas en el menú Inicio del usuario", "El asistente de accesibilidad con la lupa y el narrador", "La Configuración rápida (wifi, volumen, brillo, etc.)", "El Administrador de tareas con los procesos en ejecución"]'::jsonb,2,'Atajos de Windows','Windows + N abre el centro de notificaciones y el calendario.',null),
('adm-cm:41-246fdc8bda','adm-cm',41,'¿Qué fecha marcó el fin del soporte de Windows 10 para las ediciones domésticas y profesionales?','["El 5 de octubre de 2021", "El 31 de diciembre de 2024", "El 14 de enero de 2020", "El 14 de octubre de 2025"]'::jsonb,3,'Ciclo de vida de Windows','El 14 de enero de 2020 terminó el soporte de Windows 7 y el 5 de octubre de 2021 se lanzó Windows 11.',null),
